variables.previous_error:
{% set n=states('input_number.ph_' ~ repeat.item.z ~ '_samples')|int(0) %}
{% set e=states('input_number.ph_' ~ repeat.item.z ~ '_last_error')|float(default=none) %}
{% if n > 0 and e is number %}{{ ('+' if e > 0 else '') ~ (e|round(1)|string|replace('.',',')) ~ ' °C' }}{% else %}—{% endif %}

variables.mae_text:
{% set n=states('input_number.ph_' ~ repeat.item.z ~ '_samples')|int(0) %}
{% set m=states('input_number.ph_' ~ repeat.item.z ~ '_mae')|float(default=none) %}
{% if n > 0 and m is number %}{{ (m|round(2)|string|replace('.',',')) ~ ' °C' }}{% else %}—{% endif %}

variables.next_comfort_ts:
{% set schedule=repeat.item.schedule %}
{% set ns=namespace(ts=none) %}
{% for s in states.switch %}
  {% set entities=state_attr(s.entity_id,'entities') or [] %}
  {% set next_slot=state_attr(s.entity_id,'next_slot') %}
  {% set acts=state_attr(s.entity_id,'actions') or [] %}
  {% set nt=state_attr(s.entity_id,'next_trigger') %}
  {% if s.state == 'on' and schedule in entities and next_slot is number and nt and next_slot >= 0 and next_slot < acts|length and acts[next_slot].service == 'input_boolean.turn_on' %}
    {% set cand=as_timestamp(nt,none) %}
    {% if cand is not none and cand > as_timestamp(now()) and (ns.ts is none or cand < ns.ts) %}{% set ns.ts=cand %}{% endif %}
  {% endif %}
{% endfor %}
{{ ns.ts if ns.ts is not none else 'none' }}

variables.weather_values:
{% set target_ts=next_comfort_ts|float(default=none) %}
{% set data=ph_hourly.get('weather.forecast_domov',{}) if ph_hourly is mapping else {} %}
{% set fc=data.get('forecast',[]) if data is mapping else [] %}
{% set ns=namespace(diff=3601, row={}) %}
{% if target_ts is not none and fc is iterable and fc is not string and fc is not mapping %}
{% for f in fc if f is mapping %}
{% set ft=as_timestamp(f.get('datetime'),none) %}
{% if ft is not none and (ft-target_ts)|abs < ns.diff %}
{% set ns.diff=(ft-target_ts)|abs %}{% set ns.row=f %}
{% endif %}
{% endfor %}{% endif %}
{% set temp=ns.row.get('temperature')|float(none) %}
{% set wind=ns.row.get('wind_speed')|float(none) %}
{% set cloud=ns.row.get('cloud_coverage')|float(none) %}
{% set forecast_ok=is_number(temp) and is_number(wind) and is_number(cloud) and -80 <= temp <= 60 and 0 <= wind <= 300 and 0 <= cloud <= 100 %}
{% set current=states.weather.forecast_domov %}
{% set fresh=current is not none and current.state not in ['unknown','unavailable'] and 0 <= as_timestamp(now())-as_timestamp(current.last_updated) <= 3600 %}
{% set ct=state_attr('weather.forecast_domov','temperature')|float(none) %}
{% set cw=state_attr('weather.forecast_domov','wind_speed')|float(none) %}
{% set cc=state_attr('weather.forecast_domov','cloud_coverage')|float(none) %}
{% set current_ok=fresh and is_number(ct) and is_number(cw) and is_number(cc) and -80 <= ct <= 60 and 0 <= cw <= 300 and 0 <= cc <= 100 %}
{{ dict(quality='forecast' if forecast_ok else 'current_weather' if current_ok else 'unavailable', temperature=temp if forecast_ok else ct if current_ok else none, wind_speed=wind if forecast_ok else cw if current_ok else none, cloud_coverage=cloud if forecast_ok else cc if current_ok else none) }}

variables.lead_minutes:
{% set current=states(temp_sensor)|float(default=none) %}
{% set target=states(comfort_helper)|float(default=none) %}
{% set out=forecast_temp|float(10) %}
{% set wind=forecast_wind|float(0) %}
{% set cloud=forecast_cloud|float(50) %}
{% set rate=rate_cph|float(1.5) %}
{% set bias=bias_min|float(0) %}
{% set samples=learning_samples|int(0) %}
{% set delivery=delivery_score|float(0) %}
{% if not is_number(current) or not is_number(target) or weather_values.quality == 'unavailable' or target > 27 or target <= current + 0.2 or rate <= 0 %}
0
{% else %}
  {% set gap=target-current %}
  {% set base=(gap/rate*60) %}
  {% set cold=1.30 if out < 0 else 1.20 if out < 5 else 1.10 if out < 10 else 1.0 %}
  {% set windf=0.12 if wind >= 25 else 0.07 if wind >= 15 else 0.03 if wind >= 8 else 0 %}
  {% set sunf=-0.05 if cloud < 25 and out > 5 else 0 %}
  {% set deliveryf=0.10 if samples >= 2 and delivery < 40 else 0.05 if samples >= 2 and delivery < 60 else 0 %}
  {% set raw=base*(cold+windf+sunf+deliveryf)+10+bias %}
  {{ [[raw|round(0),0]|max,180]|min }}
{% endif %}

